import{C as i,o as h,c as g,a6 as t,E as n,j as o}from"./chunks/framework.CanHnaWe.js";const v="/IA101/images/seance-01/clavier.svg",_=JSON.parse('{"title":"Séance 1 — Comprendre la machine et bien formuler sa demande","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"seances/01-comprendre-la-machine.md","filePath":"seances/01-comprendre-la-machine.md"}'),b={name:"seances/01-comprendre-la-machine.md"},x=Object.assign(b,{setup(f){const a=[{question:"Quel élément manque à cette demande ?",code:"Dans Jumelo, ajoute un filtre par voie à la liste des offres pour que Geneviève trouve vite les offres de réseaux. Pas de code-behind, pas de nouveau paquet. Le projet compile et un test vérifie le filtre.",choix:["Objectif","Contexte","Contraintes","Critères de réussite"],bonne:1,explication:"L'agent ne sait pas où est la liste, ni que le projet utilise des classes MVVM maison. Il va chercher, ou deviner."},{question:"Et à celle-ci ?",code:"Le projet est en WPF MVVM avec nos classes maison ; la liste des offres est dans OffresViewModel. N'ajoute aucun paquet. Tous les tests doivent passer.",choix:["Objectif","Contexte","Contraintes","Critères de réussite"],bonne:0,explication:"Tout le contexte est là, mais rien ne dit ce qu'il faut faire ni pourquoi."},{question:"Et à celle-ci ?",code:"Ajoute un filtre par voie dans OffresViewModel (WPF MVVM, classes maison) pour que Geneviève trouve vite les offres de réseaux. Un test du ViewModel doit vérifier le filtre.",choix:["Objectif","Contexte","Contraintes","Critères de réussite"],bonne:2,explication:"Rien n'interdit le code-behind ni l'ajout d'un paquet. L'agent choisira le chemin le plus court, pas forcément le vôtre."},{question:"Et à la dernière ?",code:"Ajoute un filtre par voie dans OffresViewModel (WPF MVVM, classes maison) pour que Geneviève trouve vite les offres de réseaux. Pas de code-behind, pas de nouveau paquet.",choix:["Objectif","Contexte","Contraintes","Critères de réussite"],bonne:3,explication:"Comment l'agent sait-il qu'il a fini ? Sans critère vérifiable (compilation, tests), il s'arrête quand le code « a l'air bon »."}],r=[{question:"Vous posez deux fois exactement la même question à Copilot et obtenez deux réponses différentes. Pourquoi ?",choix:["Copilot a appris de votre première question.","Le modèle tire chaque token parmi plusieurs suites probables.","Le serveur était surchargé la première fois.","La deuxième réponse corrige la première."],bonne:1,explication:"La génération est un tirage, token par token. Deux tirages donnent rarement exactement le même texte."},{question:"Copilot vous propose, avec assurance, etudiants.RemoveWhere(...) sur une List<Etudiant>. Que s'est-il passé ?",choix:["Copilot a vérifié dans la documentation de .NET.","La méthode vient d'être ajoutée dans .NET 10.","Le modèle a produit une suite plausible, sans rien vérifier.","Il manque une directive using."],bonne:2,explication:"RemoveWhere existe sur HashSet<T>. Pour le modèle, c'est une suite probable ; seul le compilateur, ou vous, peut vérifier."},{question:"Après deux heures dans la même conversation, l'agent ne respecte plus une consigne donnée au début. L'explication la plus probable ?",choix:["La consigne est sortie de la fenêtre de contexte, ou s'est noyée dans tout le reste.","Le modèle se fatigue après un certain temps.","Une consigne ne vaut que pour la réponse suivante.","Votre licence Copilot a atteint sa limite."],bonne:0,explication:"Tout ce que le modèle « sait » est dans la fenêtre. Une conversation neuve, avec un fichier d'instructions, règle souvent le problème (séance 2)."},{question:"Qu'est-ce qui distingue un agent d'un chat ?",choix:["Il utilise un modèle plus gros.","Il ne se trompe pas.","Il utilise des outils, en boucle, jusqu'à atteindre l'objectif.","Il fonctionne sans connexion Internet."],bonne:2,explication:"Agent = modèle + outils + boucle. Le modèle peut être le même que dans le chat."},{question:"L'agent annonce : « Tous les tests passent, le problème est corrigé. » Que faites-vous ?",choix:["Je fais un commit tout de suite.","Je lui demande s'il est vraiment sûr.","Je relis le diff, je vérifie qu'aucun test n'a été affaibli et je lance l'application.","Je demande à un autre modèle de confirmer."],bonne:2,explication:"Un agent peut modifier un test pour le faire passer, ou corriger le mauvais endroit. Vous signez ce qui est livré."}];return(q,e)=>{const l=i("NextTokenDemo"),u=i("TokenExplorer"),d=i("ContextWindow"),c=i("VraiOuInvente"),p=i("AgentLoop"),m=i("PromptBuilder"),s=i("QuizRapide");return h(),g("div",null,[e[0]||(e[0]=t("",19)),n(l),e[1]||(e[1]=t("",4)),n(u),e[2]||(e[2]=t("",7)),n(d),e[3]||(e[3]=t("",5)),n(c),e[4]||(e[4]=t("",3)),n(p),e[5]||(e[5]=t("",8)),n(m),e[6]||(e[6]=o("p",null,[o("strong",null,"Exercice : qu'est-ce qui manque ? (5 min)")],-1)),n(s,{titre:"Qu'est-ce qui manque ?",questions:a}),e[7]||(e[7]=t("",21)),n(s,{titre:"Billet de sortie",questions:r}),e[8]||(e[8]=t("",2))])}}});export{_ as __pageData,x as default};
